package com.bank.streamutils;

import java.util.*;
import java.util.logging.*;
import static com.bank.streamutils.StreamUtils.unchecked;

public class UncheckedDemo {
    private static final Logger log = Logger.getLogger("Unchecked");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> raw = List.of("10", "20", "30");

        // method reference to a checked-throwing method, adapted via unchecked(...)
        List<Integer> parsed = raw.stream()
            .map(unchecked(UncheckedDemo::parseStrict))
            .toList();
        log.info(() -> "parsed: " + parsed);
    }

    // throws a CHECKED exception
    static int parseStrict(String s) throws Exception {
        if (!s.matches("\\d+")) throw new Exception("not a number: " + s);
        return Integer.parseInt(s);
    }
}

