@FunctionalInterface
interface CheckedFunction<T, R> {
    R apply(T t) throws Exception;   // the single abstract method declares checked exception
}

// ─── File: src/main/java/com/bank/streamutils/StreamUtils.java ───
final class StreamUtils {
    private StreamUtils() {}

    // generic adapter: CheckedFunction → Function (catch + rethrow unchecked)
    static <T, R> java.util.function.Function<T, R> unchecked(CheckedFunction<T, R> f) {
        return t -> {
            try {
                return f.apply(t);
            } catch (Exception e) {
                throw new RuntimeException(e);   // preserve cause
            }
        };
    }
}
